	n0 = strlen(bp);
	if (flags.toplin == 1 && tly == 1 &&
	    n0 + (int)strlen(toplines) + 3 < CO - 8 &&	/* leave room for
							 * --More-- */
	    strncmp(bp, "You ", 4)) {
		(void) strcat(toplines, "  ");
		(void) strcat(toplines, bp);
		tlx += 2;
		addtopl(bp);
		return;
	}
	if (flags.toplin == 1)
		more();
	remember_topl();
	dead = 0;
	toplines[0] = 0;
	while (n0 && !dead) {
		if (n0 >= CO) {
			/* look for appropriate cut point */
			n0 = 0;
			for (n = 0; n < CO; n++)
				if (bp[n] == ' ')
					n0 = n;
			if (!n0)
				for (n = 0; n < CO - 1; n++)
					if (!letter(bp[n]))
						n0 = n;
			if (!n0)
				n0 = CO - 2;
		}
		tlpos = strlen(toplines);
		tl = toplines + tlpos;
		/* avoid overflow */
		if (tlpos + n0 > (int)sizeof(toplines) - 1) {
			n0 = sizeof(toplines) - 1 - tlpos;
			dead = 1;
		}
		(void) memcpy(tl, bp, n0);
		tl[n0] = 0;
		bp += n0;

