                break;
            case DENSITY_ALGORITHM_LION:
                DENSITY_BENCHMARK_BLUE(DENSITY_BENCHMARK_BOLD(printf("Lion algorithm")));
                DENSITY_BENCHMARK_UNDERLINE(14);
                break;
        }
        fflush(stdout);

        // Pre-heat
        printf("\nUsing ");
