                printf("0x%" PRIx64 "%" PRIx64, hash_1, hash_2);
                printf(" vs. ");
                printf("0x%" PRIx64 "%" PRIx64, original_hash_1, original_hash_2);
                printf(").");, true);
            }

            printf("Uncompressed and round-trip data hashes match. ");
        }
        printf("Starting main bench.\n");
        if (compression_only)
