void wheel_count(int c,int h,int s){
    if(h==s){
        if(h==2){
            cash=cash+c+100;
        }else{
            cash=cash+c;
        }
    }
    else if(h==3 || h==4 || h==5 || h==6){
        cash=cash-10;
    }
    else if(h==32){
        cash=cash-c;
    }
    else if(h==2){
