    if not is_thumbor_enabled():
        if u.scheme == "" and u.netloc == "":
            return urlunsplit(u)
        return get_camo_url(path)

    if u.scheme == "" and u.netloc == "" and not u.path.startswith("/user_uploads/"):
        return urlunsplit(u)

